import '../core/network/api_client.dart'; import '../models/order.dart'; class OrderRepository { OrderRepository(this._api); final ApiClient _api; Future<OrderModel> create({required String addressId,required String paymentMethod,String? note,String? couponCode,List<String>? selectedCartItemIds}) async=>OrderModel.fromJson(Map<String,dynamic>.from(await _api.post('/api/orders',body:{'addressId':addressId,'paymentMethod':paymentMethod,'note':note,'couponCode':couponCode,'selectedCartItemIds':selectedCartItemIds}))); Future<List<OrderModel>> all() async { final r=await _api.get('/api/orders'); return (r as List).whereType<Map<String,dynamic>>().map(OrderModel.fromJson).toList(); } Future<OrderModel> get(String id) async=>OrderModel.fromJson(Map<String,dynamic>.from(await _api.get('/api/orders/$id'))); Future<OrderModel> cancel(String id) async=>OrderModel.fromJson(Map<String,dynamic>.from(await _api.put('/api/orders/$id/cancel'))); }